// TU-local GameSpyInfo: BFME carries seven virtuals ahead of getBuddyMap,
// so getBuddyMap lands at +0x54 and getStagingRoomList at +0x98.
class GameSpyInfo
{
public:
	virtual void slot_000(void);
	virtual void slot_004(void);
	virtual void slot_008(void);
	virtual void slot_00c(void);
	virtual void slot_010(void);
	virtual void slot_014(void);
	virtual void slot_018(void);
	virtual void slot_01c(void);
	virtual void slot_020(void);
	virtual void slot_024(void);
	virtual void slot_028(void);
	virtual void slot_02c(void);
	virtual void slot_030(void);
	virtual void slot_034(void);
	virtual void slot_038(void);
	virtual void slot_03c(void);
	virtual void slot_040(void);
	virtual void slot_044(void);
	virtual void slot_048(void);
	virtual void slot_04c(void);
	virtual void slot_050(void);
	virtual BuddyInfoMap *getBuddyMap(void);
	virtual void slot_058(void);
	virtual void slot_05c(void);
	virtual void slot_060(void);
	virtual void slot_064(void);
	virtual void slot_068(void);
	virtual void slot_06c(void);
	virtual void slot_070(void);
	virtual void slot_074(void);
	virtual void slot_078(void);
	virtual void slot_07c(void);
	virtual void slot_080(void);
	virtual void slot_084(void);
	virtual void slot_088(void);
	virtual void slot_08c(void);
	virtual void slot_090(void);
	virtual void slot_094(void);
	virtual StagingRoomMap *getStagingRoomList(void);
};

extern GameSpyInfo *TheGameSpyInfo;

// ?populateBuddyGames@@YAXXZ
void populateBuddyGames(void)
{
	BuddyInfoMap *m = TheGameSpyInfo->getBuddyMap();
	theBuddyGames = new BuddyGameSet;
	if (!m)
	{
		return;
	}
	for (BuddyInfoMap::const_iterator bit = m->begin(); bit != m->end(); ++bit)
	{
		BuddyInfo info = bit->second;
		if (info.m_status == GP_STAGING)
		{
			StagingRoomMap *srm = TheGameSpyInfo->getStagingRoomList();
			StagingRoomMap::iterator srmEnd = srm->end();
			for (StagingRoomMap::iterator srmIt = srm->begin(); srmIt != srmEnd; ++srmIt)
			{
				GameSpyStagingRoom *game = srmIt->second;
				game->cleanUpSlotPointers();
				const GameSpyGameSlot *slot = game->getGameSpySlot(0);
				if (slot != 0 && slot->getName() == info.m_locationString)
				{
					theBuddyGames->insert(game);
					break;
				}
			}
		}
	}
}
